import java.util.*;

class Solution {
  public TreeNode sortedListToBST(ListNode head) {
    List<Integer> values = new ArrayList<>();
    for (ListNode cur = head; cur != null; cur = cur.next) values.add(cur.val);
    return build(values, 0, values.size() - 1);
  }

  private TreeNode build(List<Integer> a, int lo, int hi) {
    if (lo > hi) return null;
    int mid = (lo + hi) >>> 1;
    return new TreeNode(a.get(mid), build(a, lo, mid - 1), build(a, mid + 1, hi));
  }
}
